class Solution(object):
    def smallestMissingValueSubtree(self, parents, nums):
        """
        :type parents: List[int]
        :type nums: List[int]
        :rtype: List[int]
        """
        n = len(parents)
        ans = [1] * n
        if 1 not in nums:
            return ans
        g = [[] for _ in range(n)]
        for i in range(1, n):
            g[parents[i]].append(i)

        vis = set()
        def dfs(x):
            vis.add(nums[x])
            for y in g[x]:
                if nums[y] not in vis:
                    dfs(y)

        min_num = 2
        node = nums.index(1)
        while node >= 0:
            dfs(node)
            while min_num in vis:
                min_num += 1
            ans[node] = min_num
            node = parents[node]
        return ans
